DECLARE @Process_Date DATE;
DECLARE @STG_Task_Name Varchar(100);
DECLARE @STG_Data_Layer Varchar(100);
DECLARE @EDS_Task_Name Varchar(100);
DECLARE @EDS_Data_Layer Varchar(100);
DECLARE @Operator Char(2);

SET @Process_Date = TRIM(@pProcess_Date);
SET @STG_Task_Name = TRIM(@pSTG_Task_Name);
SET @STG_Data_Layer = TRIM(@pSTG_Data_Layer);
SET @EDS_Task_Name = TRIM(@pEDS_Task_Name);
SET @EDS_Data_Layer = TRIM(@pEDS_Data_Layer);
SET @Operator = TRIM(@pOperator);


/*==========================================================================================*/
DECLARE @sqlquery NVARCHAR(MAX);

IF ((@STG_Task_Name IS NOT NULL AND @STG_Data_Layer IS NOT NULL) AND (@EDS_Task_Name IS NULL AND @EDS_Data_Layer IS NULL))
BEGIN
        SET @sqlquery = 
            'DELETE FROM OM.OM_TASK_RUN 
             WHERE TASK_NAME = ''' + @STG_Task_Name + '''' +
            ' AND CAST(Process_Date AS DATE) ' + 
            CONCAT(' ', @Operator, ' ', '''', @Process_Date, '''') +
            ' AND Data_Layer = ''' + @STG_Data_Layer + ''';';
END
ELSE IF ((@STG_Task_Name IS NULL AND @STG_Data_Layer IS NULL) AND (@EDS_Task_Name IS NOT NULL AND @EDS_Data_Layer IS NOT NULL)) 
BEGIN
        SET @sqlquery = 
        'DELETE FROM OM.OM_TASK_RUN 
        WHERE TASK_NAME = ''' + @EDS_Task_Name + ''''+
        ' AND CAST(Process_Date AS DATE) '+ CONCAT(' ',@Operator,' ','''',@Process_Date,'''')+
        ' AND Data_Layer = ''' + @EDS_Data_Layer + ''';';
END
ELSE IF ((@STG_Task_Name IS NOT NULL AND @STG_Data_Layer IS NOT NULL) AND (@EDS_Task_Name IS NOT NULL AND @EDS_Data_Layer IS NOT NULL))
BEGIN
        SET @sqlquery = 
        'DELETE FROM OM.OM_TASK_RUN 
        WHERE TASK_NAME IN (''' + @STG_Task_Name + ''', ''' + @EDS_Task_Name + ''') ' +
        ' AND CAST(Process_Date AS DATE)' + CONCAT(' ',@Operator,' ','''',@Process_Date,'''')+
        ' AND Data_Layer IN (''' + @STG_Data_Layer + ''', ''' + @EDS_Data_Layer + ''');';;
END

-- Execute the dynamic delete om logs
EXEC sp_executesql @sqlquery;

DECLARE @sql NVARCHAR(MAX);
DECLARE @tableName NVARCHAR(128);
DECLARE @baseName NVARCHAR(128);
DECLARE @SUFFIX INT = 0;
DECLARE @BU_DATE CHAR(8); -- Format: yyyyMMdd

-- Get today's date in 'yyyyMMdd' format
SET @BU_DATE = CONVERT(CHAR(8), CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'Singapore Standard Time' AS DATE), 112);
SET @baseName = 'OM_TASK_RUN_BU_' + @BU_DATE;
SET @tableName = @baseName;

-- Check if base table already exists
IF EXISTS (
    SELECT 1
    FROM INFORMATION_SCHEMA.TABLES
    WHERE TABLE_NAME = @baseName AND TABLE_SCHEMA = 'D360'
)
BEGIN
    -- Find the highest suffix number
    SELECT TOP 1 
        @SUFFIX = TRY_CAST(RIGHT(TABLE_NAME, CHARINDEX('_', REVERSE(TABLE_NAME)) - 1) AS INT)
    FROM INFORMATION_SCHEMA.TABLES
    WHERE 
        TABLE_NAME LIKE @baseName + '_%' 
        AND TABLE_SCHEMA = 'D360'
        AND ISNUMERIC(RIGHT(TABLE_NAME, CHARINDEX('_', REVERSE(TABLE_NAME)) - 1)) = 1
    ORDER BY TABLE_NAME DESC;

    -- If no _1 exists, make _1. Otherwise, increment.
    SET @SUFFIX = ISNULL(@SUFFIX, 0) + 1;
    SET @tableName = @baseName + '_' + CAST(@SUFFIX AS VARCHAR);
END

-- Build the dynamic SQL
SET @sql = '
CREATE TABLE D360.' + QUOTENAME(@tableName) + '
WITH (HEAP, DISTRIBUTION = REPLICATE)
AS 
SELECT * 
FROM OM.OM_TASK_RUN;';

-- Execute the dynamic SQL
EXEC sp_executesql @sql;
